ST.html:p:
IF FirstScan THEN
    LOOP_4750_03_TRIP := TRUE;
    LOOP_4750_01_TRIP := TRUE;
    LOOP_4712_02_TRIP := TRUE;
    LOOP_104_01_TRIP  := TRUE;
    SAFE_STATE        := TRUE;
    TV_4750_03_Out    := 6554;
    PVA_4712_02_Out   := 6554;
    XV_HS_4750_01     := FALSE;
    FirstScan         := FALSE;
    RETURN;
END_IF;

TICSA_4750_03_Scaled := ((INT_TO_REAL(TICSA_4750_03_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
PICSA_4712_02_Scaled := ((INT_TO_REAL(PICSA_4712_02_Raw) - 6554.0) / (32767.0 - 6554.0)) * 16.0;
PI_4712_01_Scaled    := ((INT_TO_REAL(PI_4712_01_Raw)    - 6554.0) / (32767.0 - 6554.0)) * 16.0;

TICSA_4750_03_HH := TICSA_4750_03_Scaled > TICSA_4750_03_HH_SP;
TICSA_4750_03_LL := TICSA_4750_03_Scaled < TICSA_4750_03_LL_SP;

TICSA_4750_03_HH_Latch(S1 := TICSA_4750_03_HH,
                        R  := TICSA_4750_03_HH_Ack AND NOT TICSA_4750_03_HH);
TICSA_4750_03_LL_Latch(S1 := TICSA_4750_03_LL,
                        R  := TICSA_4750_03_LL_Ack AND NOT TICSA_4750_03_LL);

IF TICSA_4750_03_Scaled > TICSA_4750_03_H_SP THEN
    TICSA_4750_03_H := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_H_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_H := FALSE;
END_IF;

IF TICSA_4750_03_Scaled < TICSA_4750_03_L_SP THEN
    TICSA_4750_03_L := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_L_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_L := FALSE;
END_IF;

PICSA_4712_02_HH := PICSA_4712_02_Scaled > PICSA_4712_02_HH_SP;
PICSA_4712_02_LL := PICSA_4712_02_Scaled < PICSA_4712_02_LL_SP;

PICSA_4712_02_HH_Latch(S1 := PICSA_4712_02_HH,
                        R  := PICSA_4712_02_HH_Ack AND NOT PICSA_4712_02_HH);
PICSA_4712_02_LL_Latch(S1 := PICSA_4712_02_LL,
                        R  := PICSA_4712_02_LL_Ack AND NOT PICSA_4712_02_LL);

IF PICSA_4712_02_Scaled > PICSA_4712_02_H_SP THEN
    PICSA_4712_02_H := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_H_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_H := FALSE;
END_IF;

IF PICSA_4712_02_Scaled < PICSA_4712_02_L_SP THEN
    PICSA_4712_02_L := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_L_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_L := FALSE;
END_IF;

PI_4712_01_HH_Latch(S1 := PI_4712_01_Scaled > PI_4712_01_HH_SP,
                    R  := PI_4712_01_HH_Ack AND NOT (PI_4712_01_Scaled > PI_4712_01_HH_SP));
PI_4712_01_LL_Latch(S1 := PI_4712_01_Scaled < PI_4712_01_LL_SP,
                    R  := PI_4712_01_LL_Ack AND NOT (PI_4712_01_Scaled < PI_4712_01_LL_SP));

IF PI_4712_01_Scaled > PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

IF PI_4712_01_Scaled < PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

IF TICSA_4750_03_HH OR TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := TRUE;
ELSIF LOOP_4750_03_TRIP AND MANUAL_RESET
      AND NOT TICSA_4750_03_HH AND NOT TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := FALSE;
END_IF;

IF HS_4750_01 THEN
    HS_4750_01_HH     := TRUE;
    LOOP_4750_01_TRIP := TRUE;
ELSIF LOOP_4750_01_TRIP AND MANUAL_RESET AND NOT HS_4750_01 THEN
    HS_4750_01_HH     := FALSE;
    LOOP_4750_01_TRIP := FALSE;
END_IF;
HS_4750_01_LL := FALSE;

IF PICSA_4712_02_HH OR PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := TRUE;
ELSIF LOOP_4712_02_TRIP AND MANUAL_RESET
      AND NOT PICSA_4712_02_HH AND NOT PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := FALSE;
END_IF;

IF SV_104_01_HH OR SV_104_01_LL THEN
    LOOP_104_01_TRIP := TRUE;
ELSIF LOOP_104_01_TRIP AND MANUAL_RESET
      AND NOT SV_104_01_HH AND NOT SV_104_01_LL THEN
    LOOP_104_01_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP
              OR LOOP_4750_03_TRIP
              OR LOOP_4750_01_TRIP
              OR LOOP_4712_02_TRIP
              OR LOOP_104_01_TRIP;

IF NOT SAFE_STATE THEN
    TIC_Error    := TICSA_4750_03_SP - TICSA_4750_03_Scaled;
    TIC_Integral := TIC_Integral + (TIC_Ki * TIC_Error);
    IF TIC_Integral > 100.0 THEN
        TIC_Integral := 100.0;
    ELSIF TIC_Integral < 0.0 THEN
        TIC_Integral := 0.0;
    END_IF;
    TIC_Output := (TIC_Kp * TIC_Error) + TIC_Integral;
    IF TIC_Output > 100.0 THEN
        TIC_Output := 100.0;
    ELSIF TIC_Output < 0.0 THEN
        TIC_Output := 0.0;
    END_IF;
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TIC_Output / 100.0) * (32767.0 - 6554.0));

    PIC_Error    := PICSA_4712_02_SP - PICSA_4712_02_Scaled;
    PIC_Integral := PIC_Integral + (PIC_Ki * PIC_Error);
    IF PIC_Integral > 100.0 THEN
        PIC_Integral := 100.0;
    ELSIF PIC_Integral < 0.0 THEN
        PIC_Integral := 0.0;
    END_IF;
    PIC_Output := (PIC_Kp * PIC_Error) + PIC_Integral;
    IF PIC_Output > 100.0 THEN
        PIC_Output := 100.0;
    ELSIF PIC_Output < 0.0 THEN
        PIC_Output := 0.0;
    END_IF;
    PVA_4712_02_Out := REAL_TO_INT(6554.0 + (PIC_Output / 100.0) * (32767.0 - 6554.0));

    XV_HS_4750_01         := TRUE;
    XV_HS_4750_01_Out     := TRUE;
    SV_104_01_Out         := TRUE;
    CHK_75SA21_Out        := TRUE;
    CHK_73KH12_50_D1_Out  := TRUE;
    ISOV_MNb_47121_N1_Out := TRUE;
    ISOV_MNb_47122_N2_Out := TRUE;
    ISOV_H_1007_N1_Out    := TRUE;
    ISOV_H_1007_N4_Out    := TRUE;
    ISOV_73KH12_50_P4712in_Out  := TRUE;
    ISOV_73KH12_25_PI_Out       := TRUE;
    ISOV_73KH12_50_H1008out_Out := TRUE;
    ISOV_Q_80_upstream_Out      := TRUE;
    ISOV_MNc_47125_N5_Out       := TRUE;
    ISOV_MNc_47126_H1008_Out    := TRUE;
    ISOV_73KH12_25_H1008_Out    := TRUE;
    ISOV_QSa_47140_outlet_Out   := TRUE;
    ISOV_QSb_47141_outlet_Out   := TRUE;
ELSE
    TV_4750_03_Out              := 6554;
    PVA_4712_02_Out             := 6554;
    XV_HS_4750_01               := FALSE;
    XV_HS_4750_01_Out           := FALSE;
    SV_104_01_Out               := FALSE;
    CHK_75SA21_Out              := FALSE;
    CHK_73KH12_50_D1_Out        := FALSE;
    ISOV_MNb_47121_N1_Out       := FALSE;
    ISOV_MNb_47122_N2_Out       := FALSE;
    ISOV_H_1007_N1_Out          := FALSE;
    ISOV_H_1007_N4_Out          := FALSE;
    ISOV_73KH12_50_P4712in_Out  := FALSE;
    ISOV_73KH12_25_PI_Out       := FALSE;
    ISOV_73KH12_50_H1008out_Out := FALSE;
    ISOV_Q_80_upstream_Out      := FALSE;
    ISOV_MNc_47125_N5_Out       := FALSE;
    ISOV_MNc_47126_H1008_Out    := FALSE;
    ISOV_73KH12_25_H1008_Out    := FALSE;
    ISOV_QSa_47140_outlet_Out   := FALSE;
    ISOV_QSb_47141_outlet_Out   := FALSE;
END_IF;

System_Alarm :=
    TICSA_4750_03_HH_Latch.Q1 OR TICSA_4750_03_LL_Latch.Q1 OR
    TICSA_4750_03_H            OR TICSA_4750_03_L            OR
    PICSA_4712_02_HH_Latch.Q1 OR PICSA_4712_02_LL_Latch.Q1 OR
    PICSA_4712_02_H            OR PICSA_4712_02_L            OR
    PI_4712_01_HH_Latch.Q1    OR PI_4712_01_LL_Latch.Q1    OR
    PI_4712_01_H               OR PI_4712_01_L               OR
    HS_4750_01_HH              OR HS_4750_01_LL              OR
    SV_104_01_HH               OR SV_104_01_LL               OR
    LOOP_4750_03_TRIP          OR LOOP_4750_01_TRIP          OR
    LOOP_4712_02_TRIP          OR LOOP_104_01_TRIP           OR
    SAFE_STATE;
